<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Alpaca Walk</title>
<meta name="viewport" content="width=device-width,initial-scale=1">
<style>
  html,body{margin:0;padding:0;width:100%;height:100%;overflow:hidden;background:#efdcc4;}
  canvas{display:block;position:fixed;inset:0;}
</style>
</head>
<body>
<canvas id="c"></canvas>
<script>
(function(){
const cv=document.getElementById('c');
const ctx=cv.getContext('2d');
const TAU=Math.PI*2;
let W,H,dpr,sc,ox,oy;
function resize(){
  dpr=Math.min(window.devicePixelRatio||1,2);
  W=window.innerWidth;H=window.innerHeight;
  cv.width=Math.round(W*dpr);cv.height=Math.round(H*dpr);
  cv.style.width=W+'px';cv.style.height=H+'px';
  sc=Math.max(W/1280,H/720);
  ox=(W-1280*sc)/2;oy=(H-720*sc)/2;
}
window.addEventListener('resize',resize);resize();

function rnd(i){const x=Math.sin(i*127.1+311.7)*43758.5453;return x-Math.floor(x);}
function lerp(a,b,t){return a+(b-a)*t;}

/* ---------- gait parameters ---------- */
const S=70, D=0.62, T=1.3, K=1.2;      // stride, duty factor, period, alpaca scale
const AX=590, GY=600;                    // alpaca ground origin
const SPEED=S/D/T*K;                     // ground scroll speed px/s

/* ---------- precomputed fleece ---------- */
const BCX=0,BCY=-160,BRX=96,BRY=46;
const bodyPuffs=[];
for(let i=0;i<40;i++){
  const a=i/40*TAU+rnd(i)*0.08;
  const j=1+(rnd(i+50)-0.5)*0.08;
  bodyPuffs.push({x:BCX+Math.cos(a)*BRX*j,y:BCY+Math.sin(a)*BRY*j,r:15+rnd(i+9)*7,ph:rnd(i+3)*TAU});
}
// chest & rump extra fluff
[[92,-150,22],[100,-170,18],[84,-128,18],[-92,-150,20],[-80,-128,17],[60,-200,16],[-40,-204,16],[10,-207,17]].forEach((p,i)=>bodyPuffs.push({x:p[0],y:p[1],r:p[2],ph:i}));
const curls=[];
for(let i=0;i<55;i++){
  const a=rnd(i+200)*TAU, rr=Math.sqrt(rnd(i+300));
  curls.push({x:BCX+Math.cos(a)*84*rr,y:BCY+Math.sin(a)*36*rr,r:3.5+rnd(i+400)*4,a0:rnd(i+500)*TAU});
}
const neckJ=[];
for(let i=0;i<16;i++)neckJ.push({j1:rnd(i+600)*4,j2:rnd(i+700)*4,r1:rnd(i+800)*4,r2:rnd(i+900)*4});

/* ---------- helpers ---------- */
function circlesPath(list,dx,dy,rs){
  ctx.beginPath();
  for(const p of list){const r=p.r*(rs||1);ctx.moveTo(p.x+dx+r,p.y+dy);ctx.arc(p.x+dx,p.y+dy,r,0,TAU);}
}
function limb(x1,y1,x2,y2,w1,w2){
  const a=Math.atan2(y2-y1,x2-x1),nx=-Math.sin(a),ny=Math.cos(a);
  ctx.beginPath();
  ctx.moveTo(x1+nx*w1/2,y1+ny*w1/2);
  ctx.lineTo(x2+nx*w2/2,y2+ny*w2/2);
  ctx.lineTo(x2-nx*w2/2,y2-ny*w2/2);
  ctx.lineTo(x1-nx*w1/2,y1-ny*w1/2);
  ctx.closePath();
  ctx.moveTo(x1+w1/2,y1);ctx.arc(x1,y1,w1/2,0,TAU);
  ctx.moveTo(x2+w2/2,y2);ctx.arc(x2,y2,w2/2,0,TAU);
  ctx.fill();
}
function ik(hx,hy,tx,ty,a,b,sign){
  const dx=tx-hx,dy=ty-hy;
  let d=Math.hypot(dx,dy);
  d=Math.min(d,a+b-0.5);d=Math.max(d,Math.abs(a-b)+1);
  const base=Math.atan2(dy,dx);
  const c=(a*a+d*d-b*b)/(2*a*d);
  const ang=Math.acos(Math.max(-1,Math.min(1,c)));
  const k=base+sign*ang;
  return {x:hx+Math.cos(k)*a,y:hy+Math.sin(k)*a};
}
function footPos(ph,front){
  ph=ph-Math.floor(ph);
  if(ph<D)return {x:S/2-S*ph/D,y:0,q:-1};
  const q=(ph-D)/(1-D);
  const e=q*q*(3-2*q);
  const L=front?22:17;
  return {x:-S/2+S*e,y:-L*Math.sin(Math.PI*q),q:q};
}

/* ---------- background ---------- */
function mtB(x){return 405-(170*(1-Math.abs(Math.sin(x*0.0024+3.1)))*0.75+50*(1-Math.abs(Math.sin(x*0.0067+1.1)))+8*Math.sin(x*0.027));}
function mtA(x){return 440-(150*(1-Math.abs(Math.sin(x*0.0032+0.7)))*0.7+60*(1-Math.abs(Math.sin(x*0.0081+2.2)))+12*Math.sin(x*0.031));}
function farHill(x){return 494-(22*Math.sin(x*0.004+1.3)+14*Math.sin(x*0.0093+0.4)+6*Math.sin(x*0.021));}
function nearHill(x){return 548-(16*Math.sin(x*0.0052+2.1)+10*Math.sin(x*0.012+1)+4*Math.sin(x*0.03));}

function layer(fn,off,fill){
  ctx.beginPath();ctx.moveTo(-10,730);
  for(let x=-10;x<=1290;x+=6)ctx.lineTo(x,fn(x+off));
  ctx.lineTo(1290,730);ctx.closePath();
  ctx.fillStyle=fill;ctx.fill();
}
function row(off,sp,cb){
  const base=Math.floor(off/sp);
  const n=Math.ceil(1280/sp)+2;
  for(let k=-2;k<=n;k++){const i=base+k;cb(i*sp-off,i);}
}

const clouds=[
  {x:100,y:120,s:1.1,sp:7},{x:520,y:80,s:0.8,sp:5},{x:900,y:150,s:1.3,sp:9},
  {x:1300,y:100,s:0.9,sp:6},{x:300,y:200,s:0.6,sp:4}
];
const cloudShape=[[-48,6,22],[-22,-10,30],[12,-18,34],[44,-4,26],[66,8,18],[0,8,28],[-66,12,14]];
function drawCloud(cx,cy,s){
  const g=ctx.createLinearGradient(0,cy-40*s,0,cy+30*s);
  g.addColorStop(0,'rgba(255,255,255,0.95)');
  g.addColorStop(1,'rgba(250,224,214,0.85)');
  ctx.fillStyle=g;ctx.beginPath();
  for(const c of cloudShape){ctx.moveTo(cx+c[0]*s+c[2]*s,cy+c[1]*s);ctx.arc(cx+c[0]*s,cy+c[1]*s,c[2]*s,0,TAU);}
  ctx.fill();
}

function tuft(x,y,s,seed,t,dark){
  const n=7+Math.floor(rnd(seed)*5);
  ctx.lineCap='round';
  for(let b=0;b<n;b++){
    const r1=rnd(seed*3.1+b),r2=rnd(seed*5.7+b*2.3);
    const ang=-Math.PI/2+(r1-0.5)*1.3;
    const len=s*(0.55+r2*0.5);
    const sway=Math.sin(t*1.7+x*0.012+b)*0.12*len;
    const bx=x+(r2-0.5)*s*0.25;
    const tx=bx+Math.cos(ang)*len+sway, ty=y+Math.sin(ang)*len;
    const mix=rnd(seed+b*9.1);
    const col=mix<0.45?(dark?'#8a8a3c':'#c8b45c'):(mix<0.8?(dark?'#5f7f33':'#93ad4f'):(dark?'#a08a45':'#dcc77a'));
    ctx.strokeStyle=col;ctx.lineWidth=Math.max(1.2,s/16);
    ctx.beginPath();ctx.moveTo(bx,y);
    ctx.quadraticCurveTo(bx+Math.cos(ang)*len*0.5,y+Math.sin(ang)*len*0.55,tx,ty);
    ctx.stroke();
  }
}
const flowerCols=['#fbf6f2','#f4c542','#ec7f97','#b796e6','#f29a5b'];
function flower(x,y,s,seed,t){
  const sway=Math.sin(t*1.5+x*0.02)*s*0.3;
  ctx.strokeStyle='#6f9145';ctx.lineWidth=1.2;
  ctx.beginPath();ctx.moveTo(x,y);ctx.quadraticCurveTo(x,y-s*1.2,x+sway,y-s*2.2);ctx.stroke();
  const fx=x+sway,fy=y-s*2.2;
  ctx.fillStyle=flowerCols[Math.floor(rnd(seed)*flowerCols.length)];
  for(let k=0;k<5;k++){const a=k/5*TAU;ctx.beginPath();ctx.arc(fx+Math.cos(a)*s*0.45,fy+Math.sin(a)*s*0.45,s*0.38,0,TAU);ctx.fill();}
  ctx.fillStyle='#f7d77a';ctx.beginPath();ctx.arc(fx,fy,s*0.28,0,TAU);ctx.fill();
}

function drawBackground(t,scroll){
  // sky
  const sky=ctx.createLinearGradient(0,0,0,480);
  sky.addColorStop(0,'#86b6d8');
  sky.addColorStop(0.45,'#bcd6e3');
  sky.addColorStop(0.8,'#f6dcc0');
  sky.addColorStop(1,'#f9cfa6');
  ctx.fillStyle=sky;ctx.fillRect(0,0,1280,720);
  // sun
  const sx=1010,sy=215;
  let g=ctx.createRadialGradient(sx,sy,0,sx,sy,330);
  g.addColorStop(0,'rgba(255,244,214,0.95)');
  g.addColorStop(0.12,'rgba(255,232,190,0.7)');
  g.addColorStop(0.4,'rgba(255,214,170,0.22)');
  g.addColorStop(1,'rgba(255,210,170,0)');
  ctx.fillStyle=g;ctx.fillRect(0,0,1280,720);
  ctx.fillStyle='#fff6e2';ctx.beginPath();ctx.arc(sx,sy,34,0,TAU);ctx.fill();

  // clouds
  for(const c of clouds){
    const x=((c.x+t*c.sp+scroll*0.02)%1700+1700)%1700-200;
    drawCloud(x,c.y,c.s);
  }
  // birds
  ctx.strokeStyle='rgba(70,60,70,0.55)';ctx.lineWidth=1.6;ctx.lineCap='round';
  for(let i=0;i<2;i++){
    const bx=((t*18+i*640)%1700)-200, by=135+i*40+Math.sin(t*0.4+i*2)*12;
    const w=Math.sin(t*(2.2+i*0.4)+i)*4, s=6+i*2;
    ctx.beginPath();ctx.moveTo(bx-s,by-w);ctx.quadraticCurveTo(bx-s*0.4,by-2-w*0.3,bx,by);
    ctx.quadraticCurveTo(bx+s*0.4,by-2-w*0.3,bx+s,by-w);ctx.stroke();
  }

  // mountains
  let mg=ctx.createLinearGradient(0,230,0,430);
  mg.addColorStop(0,'#fdfbfb');mg.addColorStop(0.3,'#eef0f6');mg.addColorStop(0.5,'#c3c9db');mg.addColorStop(1,'#aab2c8');
  layer(mtB,scroll*0.025,mg);
  mg=ctx.createLinearGradient(0,270,0,450);
  mg.addColorStop(0,'#fffdfb');mg.addColorStop(0.28,'#e9ebf2');mg.addColorStop(0.42,'#a3adc4');mg.addColorStop(1,'#8693ad');
  layer(mtA,scroll*0.05,mg);
  // haze
  g=ctx.createLinearGradient(0,360,0,500);
  g.addColorStop(0,'rgba(250,222,196,0)');g.addColorStop(1,'rgba(250,222,196,0.65)');
  ctx.fillStyle=g;ctx.fillRect(0,360,1280,140);

  // far hills
  g=ctx.createLinearGradient(0,460,0,560);
  g.addColorStop(0,'#b3c194');g.addColorStop(1,'#93ad79');
  layer(farHill,scroll*0.15,g);
  // shrubs on far hills
  const fo=scroll*0.15;
  row(fo,46,(x,i)=>{
    if(rnd(i*1.3)<0.55)return;
    const y=farHill(x+fo)+4;const s=4+rnd(i*2.1)*5;
    ctx.fillStyle='rgba(98,128,84,0.75)';
    ctx.beginPath();ctx.ellipse(x,y-s,s*0.8,s,0,0,TAU);ctx.fill();
  });
  // near hills / meadow
  g=ctx.createLinearGradient(0,520,0,720);
  g.addColorStop(0,'#8fb064');g.addColorStop(0.5,'#7da253');g.addColorStop(1,'#5e8a3d');
  layer(nearHill,scroll*0.35,g);
  // distant tufts on near hill
  const no=scroll*0.35;
  row(no,34,(x,i)=>{
    if(rnd(i*3.7)<0.4)return;
    const y=nearHill(x+no)+6+rnd(i)*10;
    tuft(x,y,8+rnd(i*1.9)*5,i+1000,t,true);
  });

  // back row grass (just behind trail)
  row(scroll*0.9,38,(x,i)=>{
    const y=578+rnd(i*4.4)*6;
    if(rnd(i*2.2)<0.25)flower(x+10,y,3.2,i,t);
    tuft(x,y,14+rnd(i*1.1)*8,i+2000,t,false);
  });

  // trail
  const off=scroll;
  ctx.beginPath();
  for(let x=-10;x<=1290;x+=8){const X=x+off;ctx.lineTo(x,588+3*Math.sin(X*0.02)+2*Math.sin(X*0.053));}
  for(let x=1290;x>=-10;x-=8){const X=x+off;ctx.lineTo(x,619+3*Math.sin(X*0.017+1)+2*Math.sin(X*0.061));}
  ctx.closePath();
  g=ctx.createLinearGradient(0,585,0,622);
  g.addColorStop(0,'#cdb48a');g.addColorStop(1,'#b89a6d');
  ctx.fillStyle=g;ctx.fill();
  // pebbles
  row(off,22,(x,i)=>{
    const y=592+rnd(i*5.3)*24, s=1.5+rnd(i*6.1)*2.6;
    ctx.fillStyle=rnd(i*7.7)<0.5?'rgba(140,118,88,0.7)':'rgba(230,214,186,0.8)';
    ctx.beginPath();ctx.ellipse(x,y,s*1.4,s,0,0,TAU);ctx.fill();
  });
}

function drawForeground(t,scroll){
  // mid foreground row
  row(scroll*1.3,62,(x,i)=>{
    const y=655+rnd(i*3.3)*14;
    if(rnd(i*8.1)<0.35)flower(x+18,y,4.5,i+77,t);
    if(rnd(i*9.2)<0.18){ // stone
      ctx.fillStyle='#9c9384';ctx.beginPath();ctx.ellipse(x-14,y-3,13,8,0,0,TAU);ctx.fill();
      ctx.fillStyle='rgba(255,255,255,0.25)';ctx.beginPath();ctx.ellipse(x-17,y-6,6,3,0,0,TAU);ctx.fill();
    }
    tuft(x,y,24+rnd(i*1.7)*12,i+3000,t,false);
  });
  // front row (closest)
  row(scroll*1.7,110,(x,i)=>{
    const y=712+rnd(i*2.9)*8;
    if(rnd(i*4.1)<0.4)flower(x+30,y-4,6.5,i+55,t);
    tuft(x,y,44+rnd(i*1.3)*20,i+4000,t,true);
  });
}

/* ---------- alpaca ---------- */
function drawEar(col,inner){
  ctx.fillStyle=col;ctx.beginPath();
  ctx.moveTo(-5,2);ctx.quadraticCurveTo(-8,-14,-1,-26);ctx.quadraticCurveTo(7,-14,5,2);ctx.closePath();ctx.fill();
  ctx.fillStyle=inner;ctx.beginPath();
  ctx.moveTo(-2,0);ctx.quadraticCurveTo(-4,-12,-0.5,-21);ctx.quadraticCurveTo(3.5,-12,2.5,0);ctx.closePath();ctx.fill();
}

function drawLeg(L,bob,legGrad){
  const hx=L.hx,hy=L.hy+bob;
  const f=footPos(L.ph,L.front);
  const ax=hx+f.x+(L.front?2:-3), ay=f.y-9-(L.far?3:0);
  const knee=ik(hx,hy,ax,ay,L.a,L.b,L.front?-1:1);
  const swing=f.q<0?0:Math.sin(Math.PI*f.q);
  const pa=(L.front?1.0:0.6)*swing;
  const px=ax+(4*Math.cos(pa)-9*Math.sin(pa)), py=ay+(4*Math.sin(pa)+9*Math.cos(pa));
  const lowCol=L.far?'#bfa17a':legGrad, upCol=L.far?'#c8aa82':legGrad;
  // lower leg + pastern
  ctx.fillStyle=lowCol;
  limb(knee.x,knee.y,ax,ay,12.5,9);
  limb(ax,ay,px,py,9,8.5);
  // pad / toes
  ctx.save();ctx.translate(px+3,py);ctx.rotate(-pa*0.5);
  ctx.fillStyle=L.far?'#3a2c22':'#4c3a2d';
  ctx.beginPath();ctx.ellipse(0,0,8.5,4.2,0,0,TAU);ctx.fill();
  ctx.strokeStyle=L.far?'#2a2018':'#33261d';ctx.lineWidth=1;
  ctx.beginPath();ctx.moveTo(6,-1);ctx.lineTo(9,0.5);ctx.stroke();
  ctx.restore();
  // upper leg
  ctx.fillStyle=upCol;
  limb(hx,hy,knee.x,knee.y,L.front?24:30,13.5);
  ctx.beginPath();ctx.arc(knee.x,knee.y,7.2,0,TAU);ctx.fill();
  // fluffy "pants"
  const a=Math.atan2(knee.y-hy,knee.x-hx),nx=-Math.sin(a),ny=Math.cos(a);
  const pp=[];
  for(let i=0;i<5;i++){
    const tt=i/5*0.62, r=(L.front?12.5:15.5)*(1-tt*0.55), side=(i%2?1:-1)*r*0.42;
    pp.push({x:lerp(hx,knee.x,tt)+nx*side,y:lerp(hy,knee.y,tt)+ny*side,r:r});
  }
  if(!L.far){ctx.fillStyle='rgba(176,140,96,0.45)';circlesPath(pp,0,2.5);ctx.fill();}
  ctx.fillStyle=upCol;circlesPath(pp,0,0);ctx.fill();
  if(!L.far){ctx.fillStyle='rgba(255,248,234,0.35)';circlesPath(pp,1.5,-3,0.5);ctx.fill();}
  return f;
}

function drawAlpaca(t){
  const p=t/T;
  const bob=-2.4*Math.cos(TAU*2*p)-1;
  const pitch=0.012*Math.sin(TAU*2*p+0.8);
  ctx.save();ctx.translate(AX,GY);ctx.scale(K,K);

  const bodyGrad=ctx.createLinearGradient(0,-215,0,-100);
  bodyGrad.addColorStop(0,'#fff8ec');bodyGrad.addColorStop(0.5,'#efd9b6');bodyGrad.addColorStop(1,'#d6b488');
  const legGrad=ctx.createLinearGradient(0,-125,0,0);
  legGrad.addColorStop(0,'#e8cfa6');legGrad.addColorStop(1,'#d2b48a');

  // ground shadow
  let g=ctx.createRadialGradient(0,0,10,0,0,125);
  g.addColorStop(0,'rgba(70,55,30,0.35)');g.addColorStop(1,'rgba(70,55,30,0)');
  ctx.save();ctx.scale(1,0.09);ctx.fillStyle=g;ctx.beginPath();ctx.arc(0,0,125,0,TAU);ctx.fill();ctx.restore();

  const legs=[
    {hx:-54,hy:-123,ph:p+0.5,front:false,far:true,a:58,b:66},
    {hx:70,hy:-123,ph:p+0.75,front:true,far:true,a:60,b:63},
    {hx:-62,hy:-119,ph:p,front:false,far:false,a:58,b:66},
    {hx:62,hy:-119,ph:p+0.25,front:true,far:false,a:60,b:63}
  ];
  // foot shadows
  for(const L of legs){
    const f=footPos(L.ph,L.front);
    const h=-f.y, a=0.28*(1-Math.min(1,h/25));
    ctx.fillStyle='rgba(60,45,25,'+a.toFixed(3)+')';
    ctx.beginPath();ctx.ellipse(L.hx+f.x+5,1,11,2.6,0,0,TAU);ctx.fill();
  }
  drawLeg(legs[0],bob,legGrad);
  drawLeg(legs[1],bob,legGrad);

  // body group
  ctx.save();
  ctx.translate(0,bob);
  ctx.translate(0,-150);ctx.rotate(pitch);ctx.translate(0,150);

  // tail
  ctx.save();ctx.translate(-100,-170);ctx.rotate(-0.35+0.12*Math.sin(TAU*2*p+1));
  const tp=[{x:-6,y:0,r:11},{x:-14,y:6,r:10},{x:-18,y:15,r:8},{x:-8,y:10,r:9}];
  ctx.fillStyle='#cfae80';circlesPath(tp,0,2);ctx.fill();
  ctx.fillStyle=bodyGrad;circlesPath(tp,0,0);ctx.fill();
  ctx.restore();

  // body fleece
  const jig=TAU*2*p;
  const bp=bodyPuffs.map(q=>({x:q.x,y:q.y,r:q.r+0.9*Math.sin(jig+q.ph)}));
  ctx.fillStyle='#c9a678';circlesPath(bp,0,4);ctx.fill();
  ctx.fillStyle=bodyGrad;
  ctx.beginPath();ctx.ellipse(BCX,BCY,BRX,BRY,0,0,TAU);ctx.fill();
  circlesPath(bp,0,0);ctx.fill();
  // highlights
  ctx.fillStyle='rgba(255,252,244,0.6)';
  ctx.beginPath();
  for(const q of bp){ if(q.y<BCY+8){const r=q.r*0.48;ctx.moveTo(q.x+q.r*0.15+r,q.y-q.r*0.38);ctx.arc(q.x+q.r*0.15,q.y-q.r*0.38,r,0,TAU);} }
  ctx.fill();
  // curly texture
  ctx.lineWidth=1.3;ctx.lineCap='round';
  for(const c of curls){
    ctx.strokeStyle=c.y<BCY?'rgba(196,160,112,0.35)':'rgba(170,132,88,0.38)';
    ctx.beginPath();ctx.arc(c.x,c.y,c.r,c.a0,c.a0+3.6);ctx.stroke();
  }

  // neck
  const sway=Math.sin(t*0.55)*4;
  const Tx=113+3*Math.sin(TAU*2*p+0.5)+sway, Ty=-287+1.8*Math.cos(TAU*2*p+0.5);
  const B={x:70,y:-176},C={x:104,y:-222};
  const qp=(tt)=>{const u=1-tt;return {x:u*u*B.x+2*u*tt*C.x+tt*tt*Tx,y:u*u*B.y+2*u*tt*C.y+tt*tt*Ty};};
  const qd=(tt)=>{const u=1-tt;return {x:2*u*(C.x-B.x)+2*tt*(Tx-C.x),y:2*u*(C.y-B.y)+2*tt*(Ty-C.y)};};
  const np=[];
  for(let i=0;i<16;i++){
    const tt=i/15,pt=qp(tt),d=qd(tt),l=Math.hypot(d.x,d.y),nx=-d.y/l,ny=d.x/l;
    const w=lerp(22,15,tt), r=lerp(21,14,tt), j=neckJ[i];
